import { chromium, webkit } from 'playwright';
import fs from 'node:fs';

const base=process.env.KP_AUDIT_URL||'http://127.0.0.1:4173/';
const engines=[['chromium',chromium],['webkit',webkit]];
const ids=['florian','rynek','maria','maius','wawel','dragon','szeroka','placnowy','bernatek','ghetto','tomasza','planty'];
const iso=(day,hour,min=0)=>`2026-08-${String(day).padStart(2,'0')}T${String(hour).padStart(2,'0')}:${String(min).padStart(2,'0')}:00+02:00`;
const clone=x=>JSON.parse(JSON.stringify(x));
const img=(label,c)=>`data:image/svg+xml;base64,${Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1280 960"><rect width="1280" height="960" fill="${c}"/><circle cx="1010" cy="160" r="95" fill="#f4d99a"/><path d="M0 710L200 420l200 175 220-270 210 225 180-150 300 300v260H0z" fill="#647857"/><text x="55" y="875" fill="white" font-size="54" font-family="Arial">${label}</text></svg>`).toString('base64')}`;
const colors=['#86adbf','#c59a71','#879d79','#b48768','#7896a8','#8fa671','#b58f72','#759aa4','#9d846d','#858884','#b9a47b','#8aa579'];

function stateFor(count=12,withExtra=true){
 const missionEvidence={},missionStatus={},visited=[];
 ids.slice(0,count).forEach((id,i)=>{const d=i<5?11:i<10?12:13,h=i<5?9+i:i<10?9+i-5:10+i-10,t=iso(d,h);missionEvidence[id]={id,verified:true,photo:img(id,colors[i]),title:`Recuerdo ${id}`,place:`Lugar ${id}`,comment:`Comentario del recuerdo ${id}${i===3?'. Texto largo para verificar composición, saltos de línea y legibilidad sin tapar la fotografía. '.repeat(3):'.'}`,by:i%2?'Laura':'Ismael',distance:20+i,completedAt:t,updatedAt:t};missionStatus[id]={done:true,completedAt:t,updatedAt:t};visited.push(id)});
 if(withExtra){const t=iso(12,8,50);missionEvidence.auschwitz={id:'auschwitz',extra:true,bonus:true,verified:true,photo:img('Auschwitz-Birkenau','#888780'),title:'Visita a Auschwitz-Birkenau',place:'Auschwitz-Birkenau',comment:'Una visita para recordar y aprender, con respeto y sin gamificación.',by:'Ambos',distance:64,completedAt:t,updatedAt:t}}
 return {visited,missionEvidence,missionStatus,memories:[{id:'m1',title:'La primera tarde',note:'Un recuerdo escrito largo. '.repeat(18),place:'Planty',by:'Laura',ts:iso(11,18),updatedAt:iso(11,18)},{id:'m2',title:'Algo que nos hizo gracia',note:'Un detalle pequeño que queríamos conservar.',place:'Stare Miasto',by:'Ismael',ts:iso(12,18),updatedAt:iso(12,18)}],expenses:[{id:'e1',amount:24.6,category:'food',ts:iso(11,14),updatedAt:iso(11,14)}],config:{dailyTarget:21,fixedPaid:0},updatedAt:iso(13,19)};
}
const fullState=stateFor();
const report={target:base,version:'5.0',generatedAt:new Date().toISOString(),engines:[],failures:[]};

async function newApp(engine,initial){
 let server=clone(initial);const context=await engine.launch({headless:true}).then(browser=>browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:2,acceptDownloads:true,serviceWorkers:'block'}).then(ctx=>{ctx.__browser=browser;return ctx}));
 await context.addInitScript(s=>{localStorage.setItem('krakowPocketCoop',JSON.stringify(s));localStorage.setItem('krakowPlayer','Ismael');window.__auditPrintCalled=false;window.print=()=>{window.__auditPrintCalled=true}},clone(initial));
 await context.route('https://ahzmwkztlakejmrvgcdm.supabase.co/rest/v1/rpc/**',async r=>{const u=r.request().url();if(u.includes('adventure_get'))return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(server)});if(u.includes('adventure_put')){try{const b=JSON.parse(r.request().postData()||'{}');if(b?.p_state)server=clone(b.p_state)}catch{};return r.fulfill({status:200,contentType:'application/json',body:'{}'})}return r.fulfill({status:200,contentType:'application/json',body:'{}'})});
 const page=await context.newPage();await page.goto(base,{waitUntil:'domcontentloaded',timeout:30000});await page.waitForFunction(()=>window.KP_ALBUM_V5?.version==='5.0'&&window.KP_MISSION_PROOF?.version==='2.0'&&window.KP_AUSCHWITZ_EXTRA?.version==='2.0'&&window.KP_STATE_BRIDGE?.version==='1.7',{timeout:20000});
 return {context,page,getServer:()=>server,setServer:s=>{server=clone(s)}};
}
async function closeApp(app){await app.context.close();await app.context.__browser.close()}

for(const [name,engine] of engines){
 const checks=[],errors=[];const check=(n,ok,d='')=>{checks.push({name:n,ok:!!ok,detail:d});if(!ok)report.failures.push(`${name}: ${n}${d?` — ${d}`:''}`)};
 let app;
 try{
  // Edge cases are isolated from the full-state bridge on purpose.
  for(const edge of [{label:'empty',state:{visited:[],missionEvidence:{},missionStatus:{},memories:[],expenses:[],config:{dailyTarget:21,fixedPaid:0},updatedAt:iso(11,8)},photos:0},{label:'one photo',state:stateFor(1,false),photos:1}]){
   const e=await newApp(engine,edge.state);const html=await e.page.evaluate(()=>window.KP_ALBUM_V5.html());check(`${edge.label} album has expected photo count`,(html.match(/class="photo-card/g)||[]).length===edge.photos);check(`${edge.label} album has correct Story availability`,edge.photos===0?!html.includes('id="storyAlbum"'):html.includes('id="storyAlbum"'));if(edge.photos===0)check('empty album shows useful empty state',html.includes('Todavía no hay fotografías guardadas'));await closeApp(e);
  }

  app=await newApp(engine,fullState);const {page,context}=app;page.on('pageerror',e=>errors.push(`pageerror: ${e}`));page.on('console',m=>{if(m.type()==='error'&&!/favicon|Failed to load resource/.test(m.text()))errors.push(`console: ${m.text()}`)});await page.waitForTimeout(900);await page.evaluate(()=>document.querySelector('.tab[data-panel="diary"]')?.click());await page.waitForTimeout(250);

  const arch=await page.evaluate(()=>({v5:window.KP_ALBUM_V5?.singleSource,experience:window.KP_ALBUM_EXPERIENCE?.unifiedSingleSource,proof:window.KP_MISSION_PROOF?.legacyAlbumUi===false&&window.KP_MISSION_PROOF?.legacyAlbumExporter===false,aus:window.KP_AUSCHWITZ_EXTRA?.legacyAlbumExporter===false,bridge:window.KP_STATE_BRIDGE?.staleMissionEvidenceProtection===true&&window.KP_STATE_BRIDGE?.remoteEvidenceAbsorbedBeforeAppMerge===true,legacyGlobals:!!(window.KP_ALBUM_V3_POLISH||window.KP_ALBUM_DIGITAL_V4||window.KP_ALBUM_DIGITAL_RUNTIME_FIX||window.KP_ALBUM_DIGITAL_AMBIENT_FIX),legacyDom:document.querySelectorAll('#kpAlbumCard,#kpAlbumDialog,#kpAlbumExperienceCard,#kpAlbumExperienceDialog').length,legacyScripts:[...document.scripts].filter(s=>/album-(experience|v3|digital-v4|ios-compat)/.test(s.src)).length}));
  check('single-source V5 architecture',arch.v5&&arch.experience&&arch.proof&&arch.aus&&arch.bridge&&!arch.legacyGlobals&&arch.legacyDom===0&&arch.legacyScripts===0,JSON.stringify(arch));
  await page.evaluate(()=>{window.dispatchEvent(new Event('pageshow'));window.dispatchEvent(new CustomEvent('kp:mission-evidence-sync',{detail:{}}));document.dispatchEvent(new Event('visibilitychange'))});await page.waitForTimeout(450);check('legacy album cannot reappear',(await page.locator('#kpAlbumCard,#kpAlbumDialog,#kpAlbumExperienceCard,#kpAlbumExperienceDialog').count())===0);

  const html=await page.evaluate(()=>window.KP_ALBUM_V5.html());const refs=(html.match(/data:image\//g)||[]).length;check('standalone HTML contains all 13 photos',(html.match(/class="photo-card/g)||[]).length===13);check('Auschwitz remains memory extra',html.includes('EXTRA · MEMORIA')&&html.includes('sin gamificación'));check('long text survives',html.includes('Texto largo para verificar composición')&&html.includes('Un recuerdo escrito largo'));check('HTML is self-contained',!/<script[^>]+src=/i.test(html)&&!/<link[^>]+stylesheet/i.test(html)&&!/(cdn\.jsdelivr|unpkg|googleapis)/i.test(html));check('photo embedding remains bounded',refs<=14,`${refs} refs`);check('print/reduced-motion/no-JS structure exists',html.includes('@media print')&&html.includes('prefers-reduced-motion:reduce')&&html.includes('class="js-only story-launch"'));

  // PDF before opening the album.
  const printOk=await page.evaluate(()=>window.KP_ALBUM_V5.print());await page.waitForSelector('#kpAlbumV5Dialog[open]');const f=page.frameLocator('#kpAlbumV5Frame');await f.locator('[data-kp-album-v5="1"]').waitFor({state:'visible'});const printCalled=await f.locator('body').evaluate(()=>window.__auditPrintCalled===true);check('PDF waits for loaded album',printOk&&printCalled,`api=${printOk} called=${printCalled}`);await page.locator('#kpAlbumV5Close').click();await page.waitForFunction(()=>!document.documentElement.classList.contains('kp-album-v5-open'));

  // Repeated Safari-style open/close.
  for(let i=0;i<(name==='webkit'?5:2);i++){await page.locator('#kpAlbumV5Open').click();await page.waitForSelector('#kpAlbumV5Dialog[open]');await f.locator('[data-kp-album-v5="1"]').waitFor();await page.locator('#kpAlbumV5Close').click();await page.waitForFunction(()=>!document.querySelector('#kpAlbumV5Dialog')?.open)}check('viewer survives repeated open/close',true);
  await page.locator('#kpAlbumV5Open').click();await f.locator('.photo-card').first().waitFor();check('viewer renders 13 photos',(await f.locator('.photo-card').count())===13);check('viewer groups the trip into chapters',(await f.locator('.chapter').count())>=3);check('viewer renders memories',(await f.locator('.memory-card').count())===2);

  const matrix=[];for(const width of [320,390,430,768]){await page.setViewportSize({width,height:844});await page.waitForTimeout(100);matrix.push({width,...await f.locator('html').evaluate(()=>({cw:document.documentElement.clientWidth,sw:document.documentElement.scrollWidth,toolbar:document.querySelector('.toolbar').scrollWidth-document.querySelector('.toolbar').clientWidth,minTap:Math.min(...[...document.querySelectorAll('.toolbar a,.toolbar button,.story-controls button,.overlay-close')].filter(x=>x.getBoundingClientRect().height>0).map(x=>x.getBoundingClientRect().height))}))})}check('responsive has no horizontal overflow',matrix.every(x=>x.sw<=x.cw+1),JSON.stringify(matrix));check('toolbar never clips',matrix.every(x=>x.toolbar<=1));check('touch targets stay >=40px',matrix.every(x=>x.minTap>=40));await page.setViewportSize({width:390,height:844});

  // Lightbox.
  await f.locator('.photo-button').first().click();const lb=f.locator('#lightbox');check('lightbox opens',await lb.evaluate(el=>el.classList.contains('open')));const p1=await f.locator('#lightbox img').getAttribute('src');await f.locator('.lightbox-next').click();const p2=await f.locator('#lightbox img').getAttribute('src');check('lightbox next works',p1!==p2);await f.locator('.lightbox-prev').click();check('lightbox previous works',(await f.locator('#lightbox img').getAttribute('src'))===p1);await page.keyboard.press('Escape');check('Escape closes lightbox',!(await lb.evaluate(el=>el.classList.contains('open'))));

  // Story / autoplay / pause / filmstrip.
  await f.locator('#storyAlbum').click();const story=f.locator('#storyMode');check('Story opens',await story.evaluate(el=>el.classList.contains('open')));check('filmstrip has one thumb per photo',(await f.locator('.filmstrip button').count())===13);const s1=(await f.locator('.story-position').textContent()).trim();await f.locator('#storyNext').click();const s2=(await f.locator('.story-position').textContent()).trim();check('Story next advances',s1!==s2,`${s1}->${s2}`);await f.locator('.filmstrip button').nth(4).click();check('filmstrip jump works',(await f.locator('.story-position').textContent()).includes('5 / 13'));await f.locator('.story-play').click();const before=(await f.locator('.story-position').textContent()).trim();await page.waitForTimeout(4700);const after=(await f.locator('.story-position').textContent()).trim();check('autoplay advances',before!==after,`${before}->${after}`);await f.locator('.story-play').click();const paused=(await f.locator('.story-position').textContent()).trim();await page.waitForTimeout(4700);check('pause freezes autoplay',(await f.locator('.story-position').textContent()).trim()===paused);

  // Real app save while Story is open; V5 must defer refresh until overlay closes.
  await page.evaluate(()=>{memoryTitle.value='Recuerdo en vivo';memoryNote.value='Añadido mientras Historia estaba abierto';memoryPlace.value='Cracovia';memoryForm.requestSubmit()});await page.waitForFunction(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').memories?.some(x=>x.title==='Recuerdo en vivo'));await page.waitForTimeout(1400);check('live save does not close Story',await story.evaluate(el=>el.classList.contains('open')));await f.locator('#storyMode .overlay-close').click();let live=false;try{await f.locator('text=Recuerdo en vivo').waitFor({state:'visible',timeout:4500});live=true}catch{}check('deferred refresh appears after Story closes',live);

  // Scroll preservation without smooth-scroll measurement noise.
  await f.locator('html').evaluate(()=>{document.documentElement.style.scrollBehavior='auto';scrollTo(0,180)});await page.waitForTimeout(50);const y1=await f.locator('body').evaluate(()=>scrollY);await page.evaluate(()=>{memoryTitle.value='Scroll estable';memoryNote.value='Nuevo recuerdo';memoryPlace.value='Cracovia';memoryForm.requestSubmit()});await page.waitForTimeout(1800);const y2=await f.locator('body').evaluate(()=>scrollY);check('live refresh preserves non-zero scroll',Math.abs(y2-y1)<=8,`${y1}->${y2}`);await f.locator('html').evaluate(()=>{document.documentElement.style.scrollBehavior='auto';scrollTo(0,0)});await page.evaluate(()=>{memoryTitle.value='Scroll cero';memoryNote.value='Nuevo recuerdo arriba';memoryPlace.value='Cracovia';memoryForm.requestSubmit()});await page.waitForTimeout(1800);const y0=await f.locator('body').evaluate(()=>scrollY);check('live refresh preserves zero scroll',y0===0,`0->${y0}`);

  // Let all local pushes settle, then inject a genuinely newer second-iPhone record.
  await page.waitForTimeout(1800);app.setServer(clone(await page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}'))));const remote=clone(app.getServer());const rt='2026-08-14T00:01:00+02:00';remote.missionEvidence.bernatek={...remote.missionEvidence.bernatek,title:'Recuerdo remoto de Laura',comment:'Cambio nuevo recibido desde el segundo iPhone',by:'Laura',updatedAt:rt};remote.updatedAt=rt;app.setServer(remote);await page.locator('#reconnectCloud').click();await page.waitForFunction(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title==='Recuerdo remoto de Laura',{timeout:7000});let remoteShown=false;try{await f.locator('text=Recuerdo remoto de Laura').waitFor({state:'visible',timeout:5000});remoteShown=true}catch{}check('remote evidence reaches open album',remoteShown);await page.waitForTimeout(6500);const persisted=await page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title);check('remote evidence survives later sync cycles',persisted==='Recuerdo remoto de Laura',String(persisted));const canonical=await page.evaluate(()=>window.KP_ALBUM_V5.html());check('canonical generator keeps remote evidence',canonical.includes('Recuerdo remoto de Laura'));

  // Real download uses current canonical state.
  let downloaded='';try{const [dl]=await Promise.all([page.waitForEvent('download',{timeout:5000}),page.evaluate(()=>window.KP_ALBUM_V5.download())]);const path=await dl.path();if(path)downloaded=fs.readFileSync(path,'utf8')}catch(e){errors.push(`download:${e}`)}check('downloaded HTML is current V5',downloaded.includes('data-kp-album-v5="1"')&&downloaded.includes('Recuerdo remoto de Laura')&&downloaded.includes('Auschwitz-Birkenau'),`${downloaded.length} chars`);

  const duplicateIds=await f.locator('html').evaluate(()=>{const m=new Map(),out=[];document.querySelectorAll('[id]').forEach(el=>m.set(el.id,(m.get(el.id)||0)+1));m.forEach((n,id)=>{if(n>1)out.push([id,n])});return out});check('album document has no duplicate IDs',duplicateIds.length===0,JSON.stringify(duplicateIds));await page.locator('#kpAlbumV5Close').click();await page.waitForFunction(()=>!document.documentElement.classList.contains('kp-album-v5-open'));check('closing viewer always unlocks app',true);

  // iPhone Quick Look equivalent: JavaScript disabled.
  const noJs=await context.__browser.newContext({viewport:{width:390,height:844},javaScriptEnabled:false});const np=await noJs.newPage();await np.setContent(downloaded||html,{waitUntil:'domcontentloaded'});const info=await np.evaluate(()=>({overflow:document.documentElement.scrollWidth-document.documentElement.clientWidth,story:document.querySelector('#storyAlbum')?getComputedStyle(document.querySelector('#storyAlbum')).display:'absent',photos:document.querySelectorAll('.photo-card').length,top:document.querySelector('a[href="#albumTop"]')?.href,index:document.querySelector('a[href="#albumIndex"]')?.href,pdf:document.querySelector('#albumPrint')?.getAttribute('href'),end:document.querySelector('a[href="#albumEnd"]')?.href}));check('no-JS/Quick Look keeps content + navigation',info.overflow<=1&&(info.story==='none'||info.story==='absent')&&info.photos===13&&info.top&&info.index&&info.pdf==='#pdfHelp'&&info.end,JSON.stringify(info));await noJs.close();
  check('no runtime JS errors',errors.length===0,errors.join(' | ').slice(0,1600));
 }catch(e){check('audit completed without unhandled exception',false,String(e?.stack||e).slice(0,1800))}finally{if(app)await closeApp(app);report.engines.push({engine:name,checks,errors})}
}

fs.writeFileSync('/tmp/album-v5-final-audit.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(report.failures.length)process.exitCode=1;
